<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Plus, Warning } from '@element-plus/icons-vue'
import ContractWorkbench from './ContractWorkbench.vue'
import { deleteLedger, listLedger, saveLedger, type LedgerItem, type LedgerSummary } from '../../services/personalWorkApi'

const items = ref<LedgerItem[]>([]); const summary = ref<LedgerSummary>({ total: 0, normal: 0, attention: 0, overdue: 0, contract_amount: 0, received_amount: 0 }); const dialog = ref(false)
const blank = (): LedgerItem => ({ id:'', project_name:'', project_code:'', customer:'', owner:'', stage:'机会', status:'正常', contract_amount:0, received_amount:0, contract_date:'', delivery_due:'', acceptance_due:'', payment_due:'', next_action:'', risk_note:'', updated_at:'' })
const form = reactive<LedgerItem>(blank())
const money = (v:number) => `¥${Number(v || 0).toLocaleString('zh-CN', { minimumFractionDigits: 2 })}`
async function load(){ try { const r=await listLedger(); items.value=r.items; summary.value=r.summary } catch(e){ ElMessage.error(e instanceof Error?e.message:'台账加载失败') } }
function open(item?:LedgerItem){ Object.assign(form, item ? item : blank()); dialog.value=true }
const workbenchVisible = ref(false)
function startFlow(stage:string){ if(stage === '合同') { workbenchVisible.value = true; return } Object.assign(form, blank(), { stage, next_action: stage === '回款' ? '更新付款流程并登记本次催收结果' : '核对交付节点、待签收单据与风险事项' }); dialog.value=true }
async function submit(){ if(!form.project_name.trim()) return ElMessage.warning('请填写项目名称'); try { await saveLedger(form); dialog.value=false; await load(); ElMessage.success('台账已保存') } catch(e){ ElMessage.error(e instanceof Error?e.message:'保存失败') } }
async function remove(id:string){ try { await ElMessageBox.confirm('删除后不可恢复，确认删除该台账记录？','删除台账',{type:'warning'}); await deleteLedger(id); await load(); ElMessage.success('已删除') } catch(e){ if(e !== 'cancel') ElMessage.error(e instanceof Error?e.message:'删除失败') } }
onMounted(load)
</script>

<template>
  <section class="workspace-main ledger-main">
    <ContractWorkbench v-if="workbenchVisible" />
    <header class="ledger-head"><div><p>经营协同 · 项目全周期</p><h1>项目管理台账助手</h1><span>覆盖销售合同、采购交付、验收、回款及风险跟进。</span></div><el-button type="primary" :icon="Plus" @click="open()">新建台账</el-button></header>
    <section class="ledger-stats"><article><span>在管项目</span><strong>{{ summary.total }}</strong></article><article><span>合同金额</span><strong>{{ money(summary.contract_amount) }}</strong></article><article><span>已回款</span><strong>{{ money(summary.received_amount) }}</strong></article><article class="risk"><span>关注 / 逾期</span><strong>{{ summary.attention }} / {{ summary.overdue }}</strong></article></section>
    <section class="ledger-tip"><el-icon><Warning /></el-icon><span>参考合同、采购、到货验收与项目损益测算资料设计。请持续登记关键节点和下一步动作，便于经营复盘。</span></section>
    <section class="ledger-flows"><article><h3>单据自动生成</h3><p>合同清单驱动送货、签收、验收、结算及支付申请单。</p><el-button type="primary" plain @click="startFlow('合同')">导入合同 / 新建单据任务</el-button></article><article><h3>回款与任务自动管理</h3><p>按项目编码登记发货、验收、回款节点和项目经理待办。</p><el-button type="primary" plain @click="startFlow('回款')">新建回款跟踪任务</el-button></article><article><h3>风险预警与台账管理</h3><p>逾期节点标红，集中处理待签单据、待回款与交付风险。</p><el-button type="warning" plain @click="startFlow('交付')">登记风险 / 交付事项</el-button></article></section>
    <section class="ledger-table"><el-table :data="items" empty-text="暂无台账记录，点击“新建台账”开始管理项目。"><el-table-column prop="project_name" label="项目" min-width="180"><template #default="{row}"><strong>{{ row.project_name }}</strong><small>{{ row.project_code || row.customer }}</small></template></el-table-column><el-table-column prop="stage" label="阶段" width="92"/><el-table-column prop="owner" label="负责人" width="100"/><el-table-column label="合同 / 回款" min-width="160"><template #default="{row}">{{ money(row.contract_amount) }} / {{ money(row.received_amount) }}</template></el-table-column><el-table-column label="关键节点" min-width="150"><template #default="{row}">{{ row.payment_due || row.acceptance_due || row.delivery_due || '-' }}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='逾期'?'danger':row.status==='关注'?'warning':row.status==='已完成'?'success':'info'">{{ row.status }}</el-tag></template></el-table-column><el-table-column label="操作" width="140"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button><el-button link type="danger" @click="remove(row.id)">删除</el-button></template></el-table-column></el-table></section>
    <el-dialog v-model="dialog" :title="form.id ? '编辑经营台账' : '新建经营台账'" width="min(760px,94vw)"><el-form label-position="top"><el-row :gutter="16"><el-col :span="12"><el-form-item label="项目名称"><el-input v-model="form.project_name"/></el-form-item></el-col><el-col :span="12"><el-form-item label="项目编码"><el-input v-model="form.project_code"/></el-form-item></el-col><el-col :span="12"><el-form-item label="客户"><el-input v-model="form.customer"/></el-form-item></el-col><el-col :span="12"><el-form-item label="负责人"><el-input v-model="form.owner"/></el-form-item></el-col><el-col :span="8"><el-form-item label="当前阶段"><el-select v-model="form.stage" style="width:100%"><el-option v-for="x in ['机会','合同','采购','交付','验收','回款','关闭']" :key="x" :label="x" :value="x"/></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="状态"><el-select v-model="form.status" style="width:100%"><el-option v-for="x in ['正常','关注','逾期','已完成']" :key="x" :label="x" :value="x"/></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="合同金额（元）"><el-input-number v-model="form.contract_amount" :min="0" style="width:100%"/></el-form-item></el-col><el-col :span="8"><el-form-item label="已回款（元）"><el-input-number v-model="form.received_amount" :min="0" style="width:100%"/></el-form-item></el-col><el-col :span="8"><el-form-item label="交付截止"><el-input v-model="form.delivery_due" placeholder="YYYY-MM-DD"/></el-form-item></el-col><el-col :span="8"><el-form-item label="验收截止"><el-input v-model="form.acceptance_due" placeholder="YYYY-MM-DD"/></el-form-item></el-col><el-col :span="12"><el-form-item label="回款截止"><el-input v-model="form.payment_due" placeholder="YYYY-MM-DD"/></el-form-item></el-col><el-col :span="12"><el-form-item label="下一步动作"><el-input v-model="form.next_action"/></el-form-item></el-col><el-col :span="24"><el-form-item label="风险与备注"><el-input v-model="form.risk_note" type="textarea" :rows="3"/></el-form-item></el-col></el-row></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="submit">保存台账</el-button></template></el-dialog>
  </section>
</template>

<style scoped>
.ledger-main{padding:28px}.ledger-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.ledger-head p{color:#2b70d8;margin:0}.ledger-head h1{margin:6px 0;font-size:28px}.ledger-head span{color:#748197}.ledger-stats,.ledger-flows{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.ledger-stats article,.ledger-table,.ledger-tip,.ledger-flows article{background:#fff;border:1px solid #e8edf5;border-radius:12px;padding:18px}.ledger-stats span,.ledger-table small,.ledger-flows p{display:block;color:#748197}.ledger-stats strong{font-size:22px;margin-top:8px;display:block}.ledger-stats .risk strong{color:#d16b2c}.ledger-tip{margin:16px 0;color:#526176;display:flex;gap:8px;align-items:center}.ledger-tip .el-icon{color:#dd8a21}.ledger-flows{margin-bottom:16px}.ledger-flows h3{margin:0}.ledger-flows p{min-height:40px}.ledger-table{padding:8px}@media(max-width:800px){.ledger-main{padding:16px}.ledger-stats,.ledger-flows{grid-template-columns:1fr}}
</style>
